create or replace function public.enqueue_push_for_sent_communication() returns trigger language plpgsql security definer set search_path='' as $$ declare v_secret text;v_request_id bigint;begin if new.status is distinct from 'sent' or old.status is not distinct from 'sent' then return new;end if;select ds.decrypted_secret into v_secret from vault.decrypted_secrets ds where ds.name='push_internal_secret' order by ds.created_at desc limit 1;if coalesce(v_secret,'')='' then raise warning 'Push internal secret is not configured for communication %',new.id;return new;end if;select net.http_post(url:='https://vtcmvwixfqyxqghibsla.supabase.co/functions/v1/push-send',body:=jsonb_build_object('communication_id',new.id),headers:=jsonb_build_object('Content-Type','application/json','x-push-internal-key',v_secret),timeout_milliseconds:=5000) into v_request_id;return new;exception when others then raise warning 'Push enqueue failed for communication %: %',new.id,sqlerrm;return new;end;$$;
revoke all on function public.enqueue_push_for_sent_communication() from public,anon,authenticated;
grant execute on function public.enqueue_push_for_sent_communication() to service_role;
drop trigger if exists communications_push_after_sent on public.communications;
create trigger communications_push_after_sent after update of status on public.communications for each row when (new.status='sent' and old.status is distinct from 'sent') execute function public.enqueue_push_for_sent_communication();
